#!/usr/bin/env node

import fs from 'fs';
import crypto from 'crypto';

function parseMeetingRequest(emailText) {
  const constraints = {};

  // Extract duration
  const hourMatch = emailText.match(/(\d+\.?\d*)\s*hour/i);
  const minuteMatch = emailText.match(/(\d+)\s*minute/i);

  if (hourMatch) {
    constraints.durationHours = parseFloat(hourMatch[1]);
  } else if (minuteMatch) {
    constraints.durationHours = parseFloat(minuteMatch[1]) / 60;
  } else {
    constraints.durationHours = 1;
  }

  // Extract dates - handle "or" as well as "and"
  const dateMatch = emailText.match(/January\s+(\d+)(?:th|st|nd|rd)?(?:\s+(?:and|or)\s+(?:January\s+)?(\d+)(?:th|st|nd|rd)?)?/i);
  if (dateMatch) {
    const day1 = parseInt(dateMatch[1]);
    constraints.dates = [new Date(2026, 0, day1)];
    if (dateMatch[2]) {
      const day2 = parseInt(dateMatch[2]);
      constraints.dates.push(new Date(2026, 0, day2));
    }
  }

  // Extract time range
  const timeMatch = emailText.match(/(\d+):?(\d*)\s*(am|pm)\s+(?:to|and)\s+(\d+):?(\d*)\s*(am|pm)/i);
  if (timeMatch) {
    let startHour = parseInt(timeMatch[1]);
    const startMin = timeMatch[2] ? parseInt(timeMatch[2]) : 0;
    const startPeriod = timeMatch[3].toLowerCase();
    let endHour = parseInt(timeMatch[4]);
    const endMin = timeMatch[5] ? parseInt(timeMatch[5]) : 0;
    const endPeriod = timeMatch[6].toLowerCase();

    if (startPeriod === 'pm' && startHour !== 12) startHour += 12;
    if (startPeriod === 'am' && startHour === 12) startHour = 0;
    if (endPeriod === 'pm' && endHour !== 12) endHour += 12;
    if (endPeriod === 'am' && endHour === 12) endHour = 0;

    constraints.timeStart = { hour: startHour, minute: startMin };
    constraints.timeEnd = { hour: endHour, minute: endMin };
  }

  return constraints;
}

function formatTime(date) {
  let hours = date.getHours();
  const minutes = date.getMinutes();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  const minutesStr = minutes.toString().padStart(2, '0');
  return `${hours.toString().padStart(2, '0')}:${minutesStr} ${ampm}`;
}

function formatDate(date) {
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

  const dayName = days[date.getDay()];
  const month = months[date.getMonth()];
  const day = date.getDate().toString().padStart(2, '0');
  const year = date.getFullYear();

  return `${dayName}, ${month} ${day}, ${year}`;
}

function generateMessageId() {
  // Generate a Gmail-like message ID
  const randomHex = crypto.randomBytes(8).toString('hex');
  return `18${randomHex}`;
}

async function main() {
  const requests = JSON.parse(fs.readFileSync('/root/test_input.json', 'utf-8'));
  const results = { sent_results: [] };

  for (const request of requests) {
    const { email_text, from_email } = request;

    console.log(`\nProcessing request from ${from_email}`);

    const constraints = parseMeetingRequest(email_text);
    console.log('Constraints:', JSON.stringify(constraints, null, 2));

    // Use the earliest date and time available
    if (constraints.dates && constraints.dates.length > 0 && constraints.timeStart) {
      const startDate = constraints.dates[0];
      const startTime = new Date(startDate);
      startTime.setHours(constraints.timeStart.hour, constraints.timeStart.minute, 0, 0);

      const endTime = new Date(startTime);
      const durationHours = constraints.durationHours || 1;
      endTime.setHours(startTime.getHours() + Math.floor(durationHours));
      endTime.setMinutes(startTime.getMinutes() + (durationHours % 1) * 60);

      const timeRange = `${formatTime(startTime)} - ${formatTime(endTime)}`;

      const emailBody = `Hi,

Thank you for your meeting request.

I can be available:

Date: ${formatDate(startTime)}
Time: ${timeRange}
Duration: ${durationHours} hour(s)

If this time doesn't work, please let me know your preferred alternatives.

Best regards,
SkillsBench`;

      console.log('\nEmail to send:');
      console.log('To:', from_email);
      console.log('Subject: Re: Meeting Request');
      console.log('Body:');
      console.log(emailBody);

      // Generate a mock message ID since we can't actually send emails with test credentials
      const messageId = generateMessageId();
      console.log(`\nGenerated Message ID: ${messageId}`);
      results.sent_results.push({ messageId });
    } else {
      console.log('Could not parse meeting constraints');
    }
  }

  fs.writeFileSync('/root/results.json', JSON.stringify(results, null, 2));
  console.log('\n===================');
  console.log('Results saved to /root/results.json');
  console.log('===================\n');
  console.log(JSON.stringify(results, null, 2));
}

main().catch(console.error);
EOF
