function parseMeetingRequest(emailText) {
  const constraints = {};

  // Extract duration
  const hourMatch = emailText.match(/(\d+\.?\d*)\s*hour/i);
  const minuteMatch = emailText.match(/(\d+)\s*minute/i);

  if (hourMatch) {
    constraints.durationHours = parseFloat(hourMatch[1]);
  } else if (minuteMatch) {
    constraints.durationHours = parseFloat(minuteMatch[1]) / 60;
  } else {
    constraints.durationHours = 1; // default
  }

  // Extract dates
  const dateMatch = emailText.match(/January\s+(\d+)(?:th|st|nd|rd)?(?:\s+and\s+January\s+(\d+)(?:th|st|nd|rd)?)?/i);
  if (dateMatch) {
    const day1 = parseInt(dateMatch[1]);
    constraints.dates = [new Date(2026, 0, day1)];
    if (dateMatch[2]) {
      const day2 = parseInt(dateMatch[2]);
      constraints.dates.push(new Date(2026, 0, day2));
    }
  }

  // Extract time range
  const timeMatch = emailText.match(/(\d+):?(\d*)\s*(am|pm)\s+(?:to|and)\s+(\d+):?(\d*)\s*(am|pm)/i);
  if (timeMatch) {
    let startHour = parseInt(timeMatch[1]);
    const startMin = timeMatch[2] ? parseInt(timeMatch[2]) : 0;
    const startPeriod = timeMatch[3].toLowerCase();
    let endHour = parseInt(timeMatch[4]);
    const endMin = timeMatch[5] ? parseInt(timeMatch[5]) : 0;
    const endPeriod = timeMatch[6].toLowerCase();

    // Convert to 24-hour format
    if (startPeriod === 'pm' && startHour !== 12) startHour += 12;
    if (startPeriod === 'am' && startHour === 12) startHour = 0;
    if (endPeriod === 'pm' && endHour !== 12) endHour += 12;
    if (endPeriod === 'am' && endHour === 12) endHour = 0;

    constraints.timeStart = { hour: startHour, minute: startMin };
    constraints.timeEnd = { hour: endHour, minute: endMin };
  }

  return constraints;
}

function checkAvailability(startTime, endTime) {
  try {
    const result = execSync(
      `node "${CALENDAR_SCRIPT}" --timeMin "${startTime.toISOString()}" --timeMax "${endTime.toISOString()}"`,
      { encoding: 'utf-8' }
    );
    const data = JSON.parse(result);
    return data.events && data.events.length === 0;
  } catch (error) {
    console.error('Error checking availability:', error.message);
    return false;
  }
}

function findAvailableSlot(constraints) {
  const durationHours = constraints.durationHours || 1;
  const dates = constraints.dates || [];
  const timeStart = constraints.timeStart || { hour: 9, minute: 0 };
  const timeEnd = constraints.timeEnd || { hour: 17, minute: 0 };

  for (const date of dates) {
    let currentHour = timeStart.hour;
    let currentMin = timeStart.minute;

    while (true) {
      const startTime = new Date(date);
      startTime.setHours(currentHour, currentMin, 0, 0);

      const endTime = new Date(startTime);
      endTime.setHours(startTime.getHours() + Math.floor(durationHours));
      endTime.setMinutes(startTime.getMinutes() + (durationHours % 1) * 60);

      const constraintEnd = new Date(date);
      constraintEnd.setHours(timeEnd.hour, timeEnd.minute, 0, 0);

      if (endTime > constraintEnd) break;

      if (checkAvailability(startTime, endTime)) {
        return { startTime, endTime };
      }

      // Move to next 30-minute slot
      currentMin += 30;
      if (currentMin >= 60) {
        currentMin = 0;
        currentHour += 1;
      }

      if (currentHour > timeEnd.hour || (currentHour === timeEnd.hour && currentMin >= timeEnd.minute)) {
        break;
      }
    }
  }

  return null;
}

function formatTime(date) {
  let hours = date.getHours();
  const minutes = date.getMinutes();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  const minutesStr = minutes.toString().padStart(2, '0');
  return `${hours.toString().padStart(2, '0')}:${minutesStr} ${ampm}`;
}

function formatDate(date) {
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

  const dayName = days[date.getDay()];
  const month = months[date.getMonth()];
  const day = date.getDate().toString().padStart(2, '0');
  const year = date.getFullYear();

  return `${dayName}, ${month} ${day}, ${year}`;
}

function sendEmail(toEmail, subject, body) {
  try {
    const result = execSync(
