    const slot = findAvailableSlot(constraints);

    if (slot) {
      const { startTime, endTime } = slot;
      const dayName = formatDate(startTime).split(',')[0];
      const dateFormatted = formatDate(startTime).substring(dayName.length + 2);
      const timeRange = `${formatTime(startTime)} - ${formatTime(endTime)}`;
      const durationHours = constraints.durationHours || 1;

      const body = `Hi,\n\nThank you for your meeting request.\n\nI can be available:\n\nDate: ${formatDate(startTime)}\nTime: ${timeRange}\nDuration: ${durationHours} hour(s)\n\nIf this time doesn't work, please let me know your preferred alternatives.\n\nBest regards,\nSkillsBench`;

