        results.sent_results.push({ messageId });
      } else {
        console.log('Failed to send email');
      }
    } else {
      console.log('No available slot found');
    }
  }

  // Save results
  fs.writeFileSync('/root/results.json', JSON.stringify(results, null, 2));
  console.log('\nResults saved to /root/results.json');
}

main().catch(console.error);
